import 'package:flutter/material.dart';
class ScoreButton extends StatelessWidget{final String title,points;final IconData icon;final VoidCallback onPressed;const ScoreButton({super.key,required this.title,required this.points,required this.icon,required this.onPressed});@override Widget build(BuildContext c)=>FilledButton(onPressed:onPressed,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(84),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16))),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon),Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),Text(points,style:const TextStyle(fontSize:12))]));}
